script:
macroScript AIAssetCleanup category:"3DFlowHub" tooltip:"AI 에셋 정리 도구" (
    local sel = selection as array
    if sel.count == 0 then (
        messageBox "선택된 오브젝트가 없습니다." title:"알림"
    ) else (
        undo "AI Asset Cleanup" on (
            for obj in sel do (
                try (
                    -- Reset transform and scale
                    resetScale obj
                    convertToPoly obj
                    -- Center pivot to geometry
                    obj.pivot = obj.center
                ) catch (
                    print ("Failed on: " + obj.name)
                )
            )
            messageBox "선택된 AI 에셋 정리가 완료되었습니다." title:"완료"
        )
    )
)
